data.query:
query($wherePS:ProductionSetupWhereInput, $whereM: ModeListWhereInput){
  productionSetup(where: $wherePS){
    edges{
      node{
        id
        workcenter {
          id
          shiftGroupId
        }
        modeId
        eventId
        outputs {
          edges {
            node {
              kanbanCard {
                id
                kanbanRack{
                  id productStrategyProcessId
                  productStrategy {id productId}
                }
                productionHistories(orderBy:{field:occurAt,direction:desc},first:1){
                  edges{node{occurAt}}
                }
              }
              workOrderDistributionGroup{
                id
                distributions(where: {
                  virtual: {
                    _eq: false
                  }
                }){
                  edges {
                    node {
                      id
                      laborUsage
                      machineUsage
                      setupOperators
                      productionOperators
                      workOrderProcess{
                        id
                        productStrategy {
                          id productId
                        }
                        productStrategyProcessId
                      }
                      productionHistories(orderBy:{field:occurAt,direction:desc},first:1){
                        edges{node{occurAt}}
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  modeList(where:$whereM){
    edges{
      node {
        defaultEventId
      }
    }
  }
}

data.responseTransform:
{
  "SUCCESS": false,
  "MESSAGE": "No Mode or Event Provided in Request"
}

data.variablesTransform:
(
  $R := $state.context.REQUEST.DATA;
  $L := $state.context.LOCAL;
  $wc := $R.workcenterId;
  $change := $L.productionSetup.modeId != $R.modeId;
  $m := $change ? $R.modeId : $L.productionSetup.modeId;
  $e := $L.eventId;

  $shift := $executeTransform("getShift",{ "date": $state.context.LOCAL.time, "shiftGroupId": $L.productionSetup.workcenter.shiftGroupId });



 {
   "pspayload": 
       {
         "where": {
            "id": $L.productionSetup.id
          },
          "update": {
            "modeId": $m,
            "eventId": $e
          }
        },
    "wchpayload": {
      "create": {
        "transactionTypeId": $change ? "Mode Change" : "Event Update",
        "workcenterId": $wc,
        "occurAt":  $L.time,
        "creditedAt":$shift.creditAt,
        "modeId": $m,
        "eventId": $e,
        "message": $change ? "Workcenter Mode Changed to " & $m : "Workcenter Event Update to " & $e,
        "shiftId": $shift.id

      }
    }
  }
)

